param([string]$Configuration='Release')
$ErrorActionPreference='Stop';$workspace=(Resolve-Path(Join-Path $PSScriptRoot '..')).Path;$path=Join-Path $workspace "backend/SanSo.Migrator.V4/bin/$Configuration/net9.0/Migrations";if(!(Test-Path -LiteralPath $path)){throw 'MIGRATOR_V4_OUTPUT_NOT_FOUND'};$files=@(Get-ChildItem -LiteralPath $path -Filter *.sql -File|Sort-Object Name);$actual=@($files|ForEach-Object{if($_.Name-notmatch'^([0-9]{3})_'){throw "MIGRATION_NAME_INVALID: $($_.Name)"};$Matches[1]});$expected=1..11|ForEach-Object{$_.ToString('000')};if(($actual-join',')-ne($expected-join',')){throw "MIGRATION_SEQUENCE_INVALID: $($actual-join ',')"};$fix=Get-Content -LiteralPath(Join-Path $path '011_fix_projection_period_conflict.sql')-Raw;foreach($guard in @('target_period_key','ON CONFLICT ON CONSTRAINT tax_periods_organization_id_period_key_key','calculated_amount','NEEDS_REVIEW','monetary tax result intentionally withheld')){if($fix-notmatch[regex]::Escape($guard)){throw "PROJECTION_FIX_GUARD_MISSING: $guard"}};Write-Output "MIGRATION_MANIFEST_V6_VERIFIED count=$($files.Count) range=$($actual[0])-$($actual[-1]) projection_fix=period-conflict-no-tax-guess"
